# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÜRTÜNME KUVVETİNİN MATEMATİKSEL MODELİ VE DEĞİŞKEN ANALİZİ</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1e40af">Matematiksel Model: fs = k · N</text>\n  <rect x="45" y="90" width="270" height="50" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="112" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">fs,max = ks · N   ve   fk = kk · N</text>\n  <text x="180" y="130" text-anchor="middle" font-size="10.5" fill="#334155">(Statik katsayı ks &gt; Kinetik katsayı kk)</text>\n  <text x="42" y="162" font-size="11" fill="#1e3a8a">• k: Sürtünen yüzeylerin cinsine bağlı</text>\n  <text x="50" y="178" font-size="10.5" fill="#334155">birimsiz sürtünme katsayısı (Eğim = fs / N)</text>\n  <text x="42" y="200" font-size="11" fill="#1e3a8a">• N: Yüzeyin cisme uyguladığı dik</text>\n  <text x="50" y="216" font-size="10.5" fill="#334155">tepki (normal) kuvveti (Birimi: Newton)</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#166534">Temel Fiziksel Çıkarımlar</text>\n  <text x="380" y="102" font-size="11" font-weight="bold" fill="#15803d">1. Doğru Orantı İlişkisi:</text>\n  <text x="388" y="118" font-size="10.5" fill="#334155">Yüzey cinsi sabitken normal kuvvet (N)</text>\n  <text x="388" y="134" font-size="10.5" fill="#334155">iki katına çıkarsa fs de iki katına çıkar.</text>\n  <text x="380" y="158" font-size="11" font-weight="bold" fill="#15803d">2. Yüzey Alanından Bağımsızlık:</text>\n  <text x="388" y="174" font-size="10.5" fill="#334155">Aynı cisim geniş (2S) veya dar (S) yüzeyi</text>\n  <text x="388" y="190" font-size="10.5" fill="#334155">üzerine konulduğunda N değişmediği için</text>\n  <text x="388" y="206" font-size="10.5" font-weight="bold" fill="#166534">sürtünme kuvveti (fs) değişmez!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FARKLI KUVVET DURUMLARINDA NORMAL KUVVET (N) VE SÜRTÜNME</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Yatay Düzlem (Düşey Ek Kuvvet)</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#1e40af">• Serbest Durum:</text>\n  <text x="38" y="114" font-size="10.5" fill="#334155">N = m·g  =&gt;  fs = k·m·g</text>\n  <text x="30" y="138" font-size="10.5" font-weight="bold" fill="#1e40af">• Üstten Bastıran Kuvvet (Fd):</text>\n  <text x="38" y="154" font-size="10.5" fill="#334155">N = m·g + Fd  =&gt;  fs = k·(m·g + Fd)</text>\n  <text x="30" y="178" font-size="10.5" font-weight="bold" fill="#1e40af">• Yukarı Çeken Kuvvet (Fd &lt; mg):</text>\n  <text x="38" y="194" font-size="10.5" fill="#334155">N = m·g - Fd  =&gt;  fs = k·(m·g - Fd)</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Açılı Kuvvet (F, Açı α)</text>\n  <text x="255" y="98" font-size="10.5" fill="#334155">• Yatay bileşen (Hareket ettirici):</text>\n  <text x="263" y="114" font-size="10.5" font-weight="bold" fill="#b45309">Fx = F · cos α</text>\n  <text x="255" y="138" font-size="10.5" fill="#334155">• Düşey bileşen (Yukarı yönlü):</text>\n  <text x="263" y="154" font-size="10.5" font-weight="bold" fill="#b45309">Fy = F · sin α</text>\n  <text x="255" y="178" font-size="10.5" fill="#334155">• Normal kuvvet ve sürtünme:</text>\n  <text x="263" y="194" font-size="10.5" font-weight="bold" fill="#92400e">N = m·g - F·sin α</text>\n  <text x="263" y="212" font-size="10.5" font-weight="bold" fill="#92400e">fs = k · (m·g - F·sin α)</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fce7f3" stroke="#db2777" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">3. Düşey Duvar (Yatay F)</text>\n  <text x="480" y="98" font-size="10.5" fill="#334155">• Duvara dik bastıran kuvvet:</text>\n  <text x="488" y="114" font-size="10.5" font-weight="bold" fill="#be185d">N = F  (Ağırlık dik değildir!)</text>\n  <text x="480" y="138" font-size="10.5" fill="#334155">• Maksimum sürtünme:</text>\n  <text x="488" y="154" font-size="10.5" font-weight="bold" fill="#be185d">fs,max = k · F</text>\n  <text x="480" y="178" font-size="10.5" fill="#334155">• Kaymadan durma şartı:</text>\n  <text x="488" y="194" font-size="10.5" font-weight="bold" fill="#9d174d">fs,max ≥ m·g  (Dururken fs = m·g)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÜRTÜNMELİ EĞİK DÜZLEMDE SERBEST CİSİM DİYAGRAMI VE DENKLEMLER</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Eğik Düzlem Kuvvet Bileşenleri</text>\n  <text x="40" y="102" font-size="11" fill="#14532d">• Ağırlık: G = m · g (Yere dik aşağı)</text>\n  <text x="40" y="126" font-size="11" font-weight="bold" fill="#15803d">• Düzleme Paralel Bileşen (Kaydırıcı):</text>\n  <text x="48" y="144" font-size="11" fill="#334155">Gx = m · g · sin α</text>\n  <text x="40" y="168" font-size="11" font-weight="bold" fill="#15803d">• Düzleme Dik Bileşen ve Normal Kuvvet:</text>\n  <text x="48" y="186" font-size="11" fill="#334155">N = Gy = m · g · cos α</text>\n  <text x="40" y="212" font-size="11.5" font-weight="bold" fill="#166534">• Sürtünme: fs = k · m · g · cos α</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Net Kuvvet ve İvme Analizi</text>\n  <rect x="382" y="90" width="276" height="62" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="520" y="110" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6d28d9">Aşağı Hızlanan Cisim (Gx &gt; fs):</text>\n  <text x="520" y="128" text-anchor="middle" font-size="10.5" fill="#334155">Fnet = m·g·sin α - k·m·g·cos α = m·a</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">a = g · (sin α - k · cos α)</text>\n  <rect x="382" y="162" width="276" height="64" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="520" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6d28d9">Yukarı Fırlatılan Cisim (Yavaşlayan):</text>\n  <text x="520" y="200" text-anchor="middle" font-size="10.5" fill="#334155">Gx ve fs aynı yönlüdür (aşağı doğru):</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">a = g · (sin α + k · cos α)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
